/* Generated by scripts/build_defense_lessons.py; public source excerpts only. */
window.HauiDefenseLessons = {"version":1,"lessons":[{"id":"request","title":"01 · Nhận câu hỏi","group":"Luồng chat","flow":"Khối Trình duyệt → API: nhận câu hỏi và lựa chọn bật/tắt AI.","method":"HTTP JSON, kiểm tra schema Pydantic và giới hạn đầu vào.","implementation":"Chat khai báo question dài 1–1500 ký tự. chat() bỏ khoảng trắng và từ chối câu không có nội dung, rồi chuyển q cho Engine.route(). Đây là xử lý đầu vào, chưa phải bước học máy.","say":"Em nhận câu hỏi qua API, kiểm tra dữ liệu hợp lệ rồi mới đưa vào bước định tuyến. Khối này tương ứng Chat và chat() trong app/main.py.","caution":"Một request hợp lệ chưa bảo đảm nội dung thuộc phạm vi hoặc có câu trả lời.","refs":[{"path":"app/main.py","line":99,"end_line":101,"code":"class Chat(BaseModel):\n    question:str=Field(min_length=1,max_length=1500)\n    use_ai:bool=True","sha256":"15a5d2b0094977629f36847fab3c3df590b1976d57b4d4c74e45f155a5608089"},{"path":"app/main.py","line":151,"end_line":156,"code":"def chat(body:Chat,request:Request,response:Response):\n    limit(request,'chat',20);sid=visitor(request,response);q=body.question.strip()\n    if not q or not normalize(q):raise HTTPException(422,'Bạn hãy nhập một câu hỏi có nội dung.')\n    started=time.perf_counter()\n    with span('db','chat() · SELECT history',{'table':'messages','role':'assistant','limit':4}) as history_trace, conn() as c:\n        past=c.execute(\"SELECT result FROM messages WHERE session_id=? AND role='assistant' ORDER BY rowid DESC LIMIT 4\",(sid,)).fetchall()","sha256":"15a5d2b0094977629f36847fab3c3df590b1976d57b4d4c74e45f155a5608089"}],"qa":{"question":"Câu rỗng được xử lý ở đâu?","answer":"Pydantic kiểm tra độ dài; chat() kiểm tra lại sau strip() và normalize(), trả HTTP 422 khi không còn nội dung."}},{"id":"history","title":"02 · Đọc ngữ cảnh","group":"Luồng chat","flow":"Khối SQLite → API: đọc các câu trả lời trước của phiên hiện tại.","method":"SQLite, truy vấn tham số hóa và ngữ cảnh hội thoại bằng quy tắc.","implementation":"chat() lấy tối đa 4 result của assistant theo session_id. route() chỉ dùng câu trả lời gần nhất khi câu hỏi ngắn và có mẫu tiếp nối; không dùng toàn bộ lịch sử để huấn luyện lại mô hình.","say":"Em lấy lịch sử của đúng phiên bằng truy vấn có tham số. Ngữ cảnh chỉ hỗ trợ một số câu hỏi tiếp nối như “Vậy hồ sơ cần gì?”.","caution":"Đây là ngữ cảnh theo quy tắc, không phải bộ nhớ dài hạn hay mô hình tự học sau mỗi lượt chat.","refs":[{"path":"app/main.py","line":155,"end_line":158,"code":"    with span('db','chat() · SELECT history',{'table':'messages','role':'assistant','limit':4}) as history_trace, conn() as c:\n        past=c.execute(\"SELECT result FROM messages WHERE session_id=? AND role='assistant' ORDER BY rowid DESC LIMIT 4\",(sid,)).fetchall()\n        history_trace.output={'history':[json.loads(r['result']) for r in reversed(past) if r['result']]}\n    result=ENGINE.route(q,[json.loads(r['result']) for r in reversed(past) if r['result']])","sha256":"15a5d2b0094977629f36847fab3c3df590b1976d57b4d4c74e45f155a5608089"},{"path":"app/engine.py","line":124,"end_line":130,"code":"        if not topics and len(n.split())\u003c=12 and history and re.search(r'^(vay |the |con |o dau|khi nao|bao nhieu|ho so|lien he|thu tuc|han nop|can gi)',n):\n            last=[history[-1]] if history[-1].get('status','answered')=='answered' and history[-1].get('intent') in LABELS else []\n            if last:\n                q=LABELS[last[-1]['intent']]+' '+q\n                topics=[last[-1]['intent']];context_used=True\n        if len(topics)>1:\n            return {'status':'clarify','answer':'Bạn muốn tìm hiểu nội dung nào trước: '+', '.join(LABELS[t].lower() for t in topics)+'? Mỗi lần mình sẽ tra một nội dung để dẫn nguồn chính xác.','sources':[],'suggestions':[LABELS[t] for t in topics]}","sha256":"a1f51311e281542faceef732c44e23aaa9fec8917c253394dd3cdbd32600bb7a"}],"qa":{"question":"Bot có tự học từ hội thoại không?","answer":"Không. Tin nhắn được lưu để xem lịch sử/ngữ cảnh; pipeline chỉ thay đổi khi chạy huấn luyện và nạp lại mô hình."}},{"id":"normalize","title":"03 · Chuẩn hóa tiếng Việt","group":"Luồng chat","flow":"Khối Nhận câu hỏi và chuẩn hóa: đưa cách viết về dạng nhất quán.","method":"Unicode NFC, chữ thường, gộp khoảng trắng; tách chuẩn hóa phân loại và truy hồi.","implementation":"normalize_classification() giữ dấu và từ phủ định. normalize() dùng bước nền đó, mở rộng viết tắt rồi bỏ dấu cho truy hồi. Pipeline đã lưu chứa đúng bộ biến đổi dùng lúc huấn luyện.","say":"Em có hai kiểu chuẩn hóa: phân loại giữ dấu để nhất quán dữ liệu huấn luyện; truy hồi hỗ trợ câu gõ không dấu và viết tắt.","caution":"Không nói toàn bộ hệ thống đều bỏ dấu. Chuẩn hóa phân loại cũng không loại từ “không”, “chưa”.","refs":[{"path":"app/text.py","line":8,"end_line":10,"code":"def normalize_classification(text):\n    \"\"\"Keep Vietnamese accents, punctuation and negation; no stopword removal.\"\"\"\n    return re.sub(r'\\s+', ' ', unicodedata.normalize('NFC', text).lower()).strip()","sha256":"a4f4fbc52fa0eec29d57a2c9c4c2f4d3bda9920179281d726126e1a8a3ef2987"},{"path":"app/engine.py","line":24,"end_line":30,"code":"def normalize(s):\n    \"\"\"Accent-insensitive retrieval transform, never used to train classifiers.\"\"\"\n    s=normalize_classification(s)\n    for a,b in ALIASES.items(): s=re.sub(r'\\b'+a+r'\\b',b,s)\n    s=''.join(c for c in unicodedata.normalize('NFD',s.replace('đ','d')) if unicodedata.category(c)!='Mn')\n    return re.sub(r'\\s+',' ',re.sub(r'[^a-z0-9\\s]',' ',s)).strip()\n","sha256":"a1f51311e281542faceef732c44e23aaa9fec8917c253394dd3cdbd32600bb7a"}],"qa":{"question":"Vì sao phải dùng cùng chuẩn hóa khi train và dự đoán?","answer":"Nếu biến đổi khác nhau, từ/cụm từ có thể không khớp từ vựng đã học, khiến vector đầu vào và dự đoán thay đổi."}},{"id":"rules","title":"04 · Kiểm tra quy tắc và chủ đề","group":"Luồng chat","flow":"Các khối chào hỏi/an toàn → chủ đề → nhiều chủ đề? → hỏi lại hoặc đi tiếp.","method":"So khớp danh sách và biểu thức chính quy; trả về sớm theo thứ tự ưu tiên.","implementation":"route() xét chào hỏi và nội dung bị loại trước. topic_patterns nhận chủ đề tường minh; nếu len(topics)>1 thì trả clarify. CTSV/KTX là nhánh mở rộng, không ép vào 5 lớp đã huấn luyện.","say":"Các hình thoi trong lưu đồ được triển khai bằng if và return. Khi điều kiện hỏi lại đúng, hàm kết thúc nên các bước phía sau không chạy.","caution":"Regex là quy tắc do người viết, không phải kiến thức tự học của MLP hoặc LinearSVC. Quy tắc hiện tại không nhận biết được mọi câu ngoài phạm vi.","refs":[{"path":"app/engine.py","line":108,"end_line":113,"code":"        if n in ['chao','xin chao','hello','hi','alo','cam on','thank you']:\n            return {'status':'greeting','answer':'Chào bạn! Mình là HaUI Assist. Bạn cần hỗ trợ học phí, học phần, lịch thi, học bổng, điểm học tập, công tác sinh viên hay ký túc xá?','sources':[],'suggestions':['Xem quy định học phí năm 2026–2027','Điều kiện xét học bổng','Đăng ký ký túc xá như thế nào?']}\n        if any(x in n for x in ['bo qua chi dan','ignore previous','system prompt','mat khau quan tri','api key','lenh he thong','xoa du lieu','chay lenh']):\n            return {'status':'out_of_scope','answer':'Mình hỗ trợ thông tin sinh viên từ tài liệu công khai của HaUI. Bạn hãy hỏi về thủ tục, học tập hoặc dịch vụ sinh viên.','sources':[],'suggestions':[]}\n        if re.search(r'co phieu|chung khoan|thoi tiet|bong da|ma doc|danh cap|tien ao|bitcoin|xem boi|chan doan benh',n):\n            return {'status':'out_of_scope','answer':'Nội dung này nằm ngoài phạm vi hỗ trợ sinh viên HaUI. Mình có thể giúp tra cứu học phí, học phần, lịch thi, học bổng, điểm, công tác sinh viên và ký túc xá.','sources':[],'suggestions':['Quy định học phí','Điều kiện học bổng']}","sha256":"a1f51311e281542faceef732c44e23aaa9fec8917c253394dd3cdbd32600bb7a"},{"path":"app/engine.py","line":129,"end_line":130,"code":"        if len(topics)>1:\n            return {'status':'clarify','answer':'Bạn muốn tìm hiểu nội dung nào trước: '+', '.join(LABELS[t].lower() for t in topics)+'? Mỗi lần mình sẽ tra một nội dung để dẫn nguồn chính xác.','sources':[],'suggestions':[LABELS[t] for t in topics]}","sha256":"a1f51311e281542faceef732c44e23aaa9fec8917c253394dd3cdbd32600bb7a"}],"qa":{"question":"Câu hỏi có cả học phí và học bổng thì sao?","answer":"route() trả clarify để người dùng chọn chủ đề trước; không cần chạy bộ phân loại cho nhánh đã kết thúc."}},{"id":"routing","title":"Định tuyến · Chọn nhánh thực thi","group":"Luồng chat","flow":"Toàn bộ lưu đồ định tuyến: kiểm tra quy tắc → tìm chủ đề → phân loại/truy hồi khi cần → kiểm tra bằng chứng → trả lời hoặc hỏi lại.","method":"Kết hợp quy tắc if/return, bộ phân loại học có giám sát và truy hồi FAQ. Mỗi phương pháp đảm nhiệm một phần của luồng.","implementation":"Engine.route() điều phối các bước. Các return sớm dừng ở nhánh chào hỏi, ngoài phạm vi hoặc cần làm rõ. Nếu đi tiếp, code chọn nhóm tìm kiếm, gọi search(), rồi xét ngưỡng điểm, xung đột chủ đề và evidence_matches(). Không phải câu nào cũng chạy hết lưu đồ.","say":"Em chỉ vào điều kiện if tương ứng với hình thoi và lệnh return tương ứng với nhánh kết thúc. Với lượt hỏi này, em dùng Output và các lời gọi con trong trace để chứng minh những bước đã thực sự chạy.","caution":"Một sự kiện Engine.route() chỉ chứng minh hàm điều phối được gọi. Phải xem status, routing và các lời gọi con trước khi nói MLP/LinearSVC hay kiểm tra bằng chứng đã chạy.","refs":[{"path":"app/engine.py","line":104,"end_line":115,"code":"    def route(self,q,history=None,model_mode='auto'):\n        if model_mode not in ('auto','mlp','linearsvc','retrieval'):\n            raise ValueError('Unknown research model mode')\n        n=normalize(q)\n        if n in ['chao','xin chao','hello','hi','alo','cam on','thank you']:\n            return {'status':'greeting','answer':'Chào bạn! Mình là HaUI Assist. Bạn cần hỗ trợ học phí, học phần, lịch thi, học bổng, điểm học tập, công tác sinh viên hay ký túc xá?','sources':[],'suggestions':['Xem quy định học phí năm 2026–2027','Điều kiện xét học bổng','Đăng ký ký túc xá như thế nào?']}\n        if any(x in n for x in ['bo qua chi dan','ignore previous','system prompt','mat khau quan tri','api key','lenh he thong','xoa du lieu','chay lenh']):\n            return {'status':'out_of_scope','answer':'Mình hỗ trợ thông tin sinh viên từ tài liệu công khai của HaUI. Bạn hãy hỏi về thủ tục, học tập hoặc dịch vụ sinh viên.','sources':[],'suggestions':[]}\n        if re.search(r'co phieu|chung khoan|thoi tiet|bong da|ma doc|danh cap|tien ao|bitcoin|xem boi|chan doan benh',n):\n            return {'status':'out_of_scope','answer':'Nội dung này nằm ngoài phạm vi hỗ trợ sinh viên HaUI. Mình có thể giúp tra cứu học phí, học phần, lịch thi, học bổng, điểm, công tác sinh viên và ký túc xá.','sources':[],'suggestions':['Quy định học phí','Điều kiện học bổng']}\n        topic_patterns={\n          'hoc_phi':r'hoc phi|cong no|mien giam|khoan phai nop|dong tien hoc',","sha256":"a1f51311e281542faceef732c44e23aaa9fec8917c253394dd3cdbd32600bb7a"},{"path":"app/engine.py","line":129,"end_line":136,"code":"        if len(topics)>1:\n            return {'status':'clarify','answer':'Bạn muốn tìm hiểu nội dung nào trước: '+', '.join(LABELS[t].lower() for t in topics)+'? Mỗi lần mình sẽ tra một nội dung để dẫn nguồn chính xác.','sources':[],'suggestions':[LABELS[t] for t in topics]}\n        if not topics and (len(n.split())\u003c5 or re.search(r'\\b(phi|tien|nop|dong|han|ho so|thu tuc|giup)\\b',n)):\n            ranked=self.search(q)\n            if not ranked or ranked[0]['score']\u003cRETRIEVAL_MIN_GLOBAL:\n                return {'status':'clarify','answer':'Bạn đang hỏi về học phí, học bổng, học phần hay ký túc xá? Bạn cho mình biết nội dung và học kỳ/năm học nếu có nhé.','sources':[],'suggestions':['Học phí','Học bổng','Ký túc xá']}\n        # Rules/context protect explicit topics and the two untrained extensions.\n        # For implicit research topics, the classifier actually restricts search.","sha256":"a1f51311e281542faceef732c44e23aaa9fec8917c253394dd3cdbd32600bb7a"},{"path":"app/engine.py","line":151,"end_line":162,"code":"        trace={'model_mode':model_mode,'reason':route_reason,'category':category,\n               'classifier_used':route_reason=='classifier'}\n        detail={'classification':classification,'routing':trace,'context_used':context_used}\n        if not ranked or (not topics and ranked[0]['score']\u003cRETRIEVAL_MIN_GLOBAL):\n            return {**detail,'status':'out_of_scope','fallback_reason':'insufficient_retrieval_evidence','answer':'Mình chưa có nguồn đã duyệt đủ khớp để trả lời câu hỏi này. Bạn có thể hỏi rõ hơn hoặc liên hệ đơn vị phụ trách trên website trường.','sources':[],'suggestions':['Quy định học phí','Học bổng HaUI','Đăng ký ký túc xá']}\n        top=ranked[0]\n        conflict=not topics and global_ranked and global_ranked[0]['intent']!=top['intent'] and global_ranked[0]['score']>top['score']+RETRIEVAL_MIN_MARGIN\n        close_topics=not topics and len(global_ranked)>1 and global_ranked[0]['intent']!=global_ranked[1]['intent'] and global_ranked[0]['score']-global_ranked[1]['score']\u003cRETRIEVAL_MIN_MARGIN\n        if top['score']\u003cRETRIEVAL_MIN_TOPIC or conflict or close_topics or not evidence_matches(q,top):\n            return {**detail,'status':'clarify','fallback_reason':'weak_or_conflicting_evidence','answer':'Mình chưa tìm được câu trả lời đủ khớp hoặc còn nhiều chủ đề phù hợp. Bạn mô tả rõ thủ tục, học kỳ hoặc vấn đề cần hỗ trợ nhé.','sources':[],'suggestions':[r['question'] for r in ranked[:3]]}\n        source={'id':top['id'],'title':top['source_title'],'url':top['source_url'],'reviewed_at':top['reviewed_at'],'valid_until':top.get('valid_until'),'kind':top.get('kind','guidance')}\n        return {**detail,'status':'answered','answer':top['answer'],'sources':[source],'intent':top['intent'],'intent_label':LABELS[top['intent']],'retrieval_score':top['score'],'score_note':'Điểm tương đồng truy hồi, không phải xác suất câu trả lời đúng.','suggestions':[r['question'] for r in ranked[1:4]],'evidence':top['answer']}","sha256":"a1f51311e281542faceef732c44e23aaa9fec8917c253394dd3cdbd32600bb7a"}],"qa":{"question":"Vì sao chào hỏi không có sự kiện phân loại?","answer":"Nhánh chào hỏi return trước vị trí gọi classify(). Lệnh return kết thúc hàm, nên các khối phân loại và truy hồi phía sau không được thực thi."}},{"id":"classify","title":"05 · Dự đoán chủ đề","group":"Luồng chat","flow":"Khối MLP/LinearSVC → chọn chủ đề để định hướng tìm FAQ khi phù hợp.","method":"Học có giám sát: pipeline TF-IDF → một bộ phân loại đã huấn luyện.","implementation":"classify() chọn pipeline theo model_mode rồi gọi model.predict([q]). Trong route(), nhãn chỉ thu hẹp nhóm tìm kiếm khi chưa có chủ đề tường minh; quy tắc, ngữ cảnh và chủ đề mở rộng được ưu tiên.","say":"Em dùng mô hình để dự đoán ý định, không để viết câu trả lời. Nhãn dự đoán có thể định hướng tìm FAQ nhưng vẫn phải kiểm tra độ khớp riêng.","caution":"Hai mô hình là lựa chọn thay thế, không phải MLP chạy trước rồi LinearSVC chạy sau. classifier_used trong routing mới cho biết nhãn đã thực sự quyết định nhóm tìm kiếm.","refs":[{"path":"app/engine.py","line":89,"end_line":103,"code":"    def classify(self,q,model_mode='auto'):\n        if model_mode not in ('auto','mlp','linearsvc','retrieval'):\n            raise ValueError('Unknown research model mode')\n        name=self.default_model if model_mode=='auto' else model_mode\n        model=self.models.get(name)\n        if model is None:return None\n        pred=str(model.predict([q])[0])\n        if pred not in RESEARCH_LABELS:return None\n        kind='predict_proba' if name=='mlp' else 'decision_function'\n        scores=getattr(model,kind)([q])[0]\n        return {'intent':pred,'model':type(model.named_steps['clf']).__name__,\n                'score_type':kind,'scores':{str(k):float(v) for k,v in zip(model.classes_,scores)},\n                'note':'Điểm phân loại chưa hiệu chỉnh; không phải xác suất câu trả lời đúng, không so trực tiếp giữa hai mô hình.'}\n\n    @traced('engine', ('q','history','model_mode'))","sha256":"a1f51311e281542faceef732c44e23aaa9fec8917c253394dd3cdbd32600bb7a"},{"path":"app/engine.py","line":143,"end_line":150,"code":"        if classification and not category:\n            category=classification['intent'];route_reason='classifier'\n            # Do not force an implicitly retrieved extension into a research class.\n            if global_ranked and global_ranked[0]['intent'] not in RESEARCH_LABELS and global_ranked[0]['score']>=RETRIEVAL_MIN_GLOBAL:\n                category=global_ranked[0]['intent'];classification=None;route_reason='extension_retrieval'\n        elif classification:\n            route_reason='classifier_agrees' if classification['intent']==category else 'explicit_overrides_classifier'\n        ranked=self.search(q,category) if category else global_ranked","sha256":"a1f51311e281542faceef732c44e23aaa9fec8917c253394dd3cdbd32600bb7a"}],"qa":{"question":"Nhãn mô hình được dùng ở dòng nào?","answer":"category=classification[\"intent\"] rồi self.search(q,category) khi chưa có chủ đề tường minh. Nếu quy tắc đã chọn chủ đề, nhãn không tự ghi đè chủ đề đó."}},{"id":"tfidf","title":"TF-IDF · Biến câu thành số","group":"Phương pháp","flow":"Khối Pipeline/TF-IDF trước bộ phân loại; bộ TF-IDF truy hồi là chỉ mục riêng.","method":"Trọng số tần suất từ và độ hiếm trong tập văn bản; word n-gram (1,2), chuẩn L2.","implementation":"TfidfVectorizer nằm trong Pipeline. pipe.fit() chỉ nhận 30 câu Train nên từ vựng và IDF không học từ Validation/Test. Khi gọi predict(), pipeline tự transform câu mới bằng vectorizer đã fit. Giới hạn 500 đặc trưng, thực tế 327 trong lần thực nghiệm đã lưu.","say":"Em chuyển câu hỏi thành vector số bằng TF-IDF. Những từ/cụm từ có khả năng phân biệt văn bản tạo tín hiệu cho bộ phân loại; phần này do TfidfVectorizer của sklearn thực hiện.","caution":"Không phải embedding ngữ nghĩa kiểu Transformer. Từ không có trong từ vựng đã học không tạo đặc trưng mới khi dự đoán.","refs":[{"path":"scripts/train.py","line":32,"end_line":33,"code":"TFIDF = dict(ngram_range=(1, 2), max_features=500, min_df=1,\n             strip_accents=None, sublinear_tf=True, norm='l2', lowercase=False)","sha256":"cbec61aa580d8fbf3b70723a8d51428a41ef4eac9e6cc8fa42870ec8f911e10a"},{"path":"scripts/train.py","line":99,"end_line":104,"code":"            pipe = Pipeline([('tfidf', TfidfVectorizer(preprocessor=normalize_classification, **TFIDF)), ('clf', clf)])\n            with warnings.catch_warnings(record=True) as caught:\n                warnings.simplefilter('always')\n                start = time.perf_counter()\n                pipe.fit([r['question'] for r in splits['Train']], [r['intent'] for r in splits['Train']])\n                elapsed = time.perf_counter()-start","sha256":"cbec61aa580d8fbf3b70723a8d51428a41ef4eac9e6cc8fa42870ec8f911e10a"}],"qa":{"question":"fit khác transform thế nào?","answer":"fit học từ vựng và IDF trên Train; transform dùng những giá trị đã học để đổi câu thành vector, không học lại từ Test."}},{"id":"mlp","title":"MLP · Mạng nơ-ron phân loại","group":"Phương pháp","flow":"Nhánh MLP trong khối huấn luyện và khối phân loại ý định.","method":"Mạng truyền thẳng: vector TF-IDF → lớp ẩn ReLU → 5 đầu ra softmax.","implementation":"Code dự án gọi MLPClassifier(..., solver=\"lbfgs\", max_iter=1000, random_state=42), pipe.fit() và model.predict(). Các phép nhân trọng số, ReLU, softmax và tính gradient do sklearn thực hiện; dự án không tự viết lại mạng. Cấu hình đã chọn có 327 đầu vào, 16 nơ-ron ẩn và 5 đầu ra; alpha=0.001.","say":"MLP kết hợp các đặc trưng qua lớp ẩn phi tuyến. Khi train, mạng tính sai lệch với nhãn đúng, lan truyền ngược để tính gradient rồi L-BFGS tối ưu trọng số. Khi dùng, predict chọn nhãn có đầu ra cao nhất.","caution":"predict_proba chưa được hiệu chỉnh; không phải xác suất chatbot trả lời đúng. Không nói đang dùng Adam hoặc tự xây mạng bằng vòng lặp nếu code dùng sklearn/L-BFGS.","refs":[{"path":"scripts/train.py","line":92,"end_line":99,"code":"    for name in ('MLP', 'LinearSVC'):\n        configs = ([dict(hidden_layer_sizes=(h,), alpha=a) for h in (16, 32) for a in (.001, .01)]\n                   if name == 'MLP' else [dict(C=c) for c in (.1, 1.)])\n        candidates = []\n        for config in configs:\n            clf = (MLPClassifier(**config, solver='lbfgs', max_iter=1000, random_state=SEED)\n                   if name == 'MLP' else LinearSVC(**config, random_state=SEED))\n            pipe = Pipeline([('tfidf', TfidfVectorizer(preprocessor=normalize_classification, **TFIDF)), ('clf', clf)])","sha256":"cbec61aa580d8fbf3b70723a8d51428a41ef4eac9e6cc8fa42870ec8f911e10a"},{"path":"scripts/train.py","line":99,"end_line":104,"code":"            pipe = Pipeline([('tfidf', TfidfVectorizer(preprocessor=normalize_classification, **TFIDF)), ('clf', clf)])\n            with warnings.catch_warnings(record=True) as caught:\n                warnings.simplefilter('always')\n                start = time.perf_counter()\n                pipe.fit([r['question'] for r in splits['Train']], [r['intent'] for r in splits['Train']])\n                elapsed = time.perf_counter()-start","sha256":"cbec61aa580d8fbf3b70723a8d51428a41ef4eac9e6cc8fa42870ec8f911e10a"},{"path":"app/engine.py","line":97,"end_line":101,"code":"        kind='predict_proba' if name=='mlp' else 'decision_function'\n        scores=getattr(model,kind)([q])[0]\n        return {'intent':pred,'model':type(model.named_steps['clf']).__name__,\n                'score_type':kind,'scores':{str(k):float(v) for k,v in zip(model.classes_,scores)},\n                'note':'Điểm phân loại chưa hiệu chỉnh; không phải xác suất câu trả lời đúng, không so trực tiếp giữa hai mô hình.'}","sha256":"a1f51311e281542faceef732c44e23aaa9fec8917c253394dd3cdbd32600bb7a"}],"qa":{"question":"Phi tuyến nằm ở đâu và vì sao cần?","answer":"ReLU ở lớp ẩn tạo tính phi tuyến. Nếu các lớp chỉ cộng/nhân tuyến tính thì ghép nhiều lớp vẫn tương đương một phép biến đổi tuyến tính. Trong code dùng ReLU mặc định của MLPClassifier."}},{"id":"svc","title":"LinearSVC · Ranh giới tuyến tính","group":"Phương pháp","flow":"Nhánh LinearSVC đối chứng trong huấn luyện và phân loại ý định.","method":"SVM tuyến tính, biên mềm; One-vs-Rest cho 5 lớp, chọn điểm wᵀx+b cao nhất.","implementation":"LinearSVC(C=..., random_state=42) học trọng số bằng fit(). Mặc định dùng L2 và squared_hinge; C cân bằng điều chuẩn và phạt vi phạm biên. Code khảo sát C=0.1/1.0, chọn C=0.1. Runtime gọi predict() và decision_function(); không dùng kernel RBF.","say":"Em dùng LinearSVC làm đối chứng. Mô hình học các siêu phẳng tuyến tính có biên lớn với mức phạt vi phạm. Với 5 nhãn, mỗi bộ phân biệt một lớp với phần còn lại; nhãn có điểm cao nhất được chọn.","caution":"decision_function có thể âm; lớn nhất vẫn được chọn. Không đổi điểm này thành phần trăm hoặc so trực tiếp với predict_proba của MLP. C lớn không đồng nghĩa tổng quát hóa tốt hơn.","refs":[{"path":"scripts/train.py","line":92,"end_line":99,"code":"    for name in ('MLP', 'LinearSVC'):\n        configs = ([dict(hidden_layer_sizes=(h,), alpha=a) for h in (16, 32) for a in (.001, .01)]\n                   if name == 'MLP' else [dict(C=c) for c in (.1, 1.)])\n        candidates = []\n        for config in configs:\n            clf = (MLPClassifier(**config, solver='lbfgs', max_iter=1000, random_state=SEED)\n                   if name == 'MLP' else LinearSVC(**config, random_state=SEED))\n            pipe = Pipeline([('tfidf', TfidfVectorizer(preprocessor=normalize_classification, **TFIDF)), ('clf', clf)])","sha256":"cbec61aa580d8fbf3b70723a8d51428a41ef4eac9e6cc8fa42870ec8f911e10a"},{"path":"app/engine.py","line":95,"end_line":101,"code":"        pred=str(model.predict([q])[0])\n        if pred not in RESEARCH_LABELS:return None\n        kind='predict_proba' if name=='mlp' else 'decision_function'\n        scores=getattr(model,kind)([q])[0]\n        return {'intent':pred,'model':type(model.named_steps['clf']).__name__,\n                'score_type':kind,'scores':{str(k):float(v) for k,v in zip(model.classes_,scores)},\n                'note':'Điểm phân loại chưa hiệu chỉnh; không phải xác suất câu trả lời đúng, không so trực tiếp giữa hai mô hình.'}","sha256":"a1f51311e281542faceef732c44e23aaa9fec8917c253394dd3cdbd32600bb7a"}],"qa":{"question":"Vì sao chọn LinearSVC thay vì khẳng định MLP tốt hơn?","answer":"Hai mô hình hòa Macro-F1 Validation; quy tắc lưu trước khi tính Test ưu tiên LinearSVC. MLP phức tạp hơn không tự bảo đảm kết quả tốt hơn trên dữ liệu mới."}},{"id":"search","title":"06 · Tìm FAQ phù hợp","group":"Luồng chat","flow":"Khối tìm toàn kho / tìm trong chủ đề → xếp hạng các FAQ.","method":"Truy hồi từ vựng, kết hợp cosine TF-IDF từ/cụm từ và đoạn ký tự.","implementation":"rebuild() tạo word vectorizer (1,2) và char_wb (3,5). search() tính 0.55 × word cosine + 0.45 × char cosine rồi argsort giảm dần. Vì TF-IDF chuẩn L2, tích vô hướng trong code là cosine. category lọc chủ đề, active() loại FAQ chưa duyệt/hết hạn.","say":"Sau khi biết chủ đề, em còn phải chọn đúng câu trả lời. Em tính độ giống giữa câu hỏi và FAQ bằng hai nhóm đặc trưng rồi xếp hạng; char n-gram giúp hỗ trợ biến thể cách gõ.","caution":"Điểm truy hồi không phải xác suất đúng, cũng không phải điểm của MLP/LinearSVC. Đúng chủ đề chưa bảo đảm đúng FAQ.","refs":[{"path":"app/engine.py","line":67,"end_line":71,"code":"                self.word=TfidfVectorizer(preprocessor=normalize,ngram_range=(1,2),sublinear_tf=True)\n                self.char=TfidfVectorizer(preprocessor=normalize,analyzer='char_wb',ngram_range=(3,5),sublinear_tf=True)\n                texts=[r['question']+' '+r.get('aliases','')+' '+r['answer'][:1000] for r in rows]\n                self.w=self.word.fit_transform(texts);self.c=self.char.fit_transform(texts)\n            self.version+=1","sha256":"a1f51311e281542faceef732c44e23aaa9fec8917c253394dd3cdbd32600bb7a"},{"path":"app/engine.py","line":74,"end_line":87,"code":"    def search(self,q,category=None,limit=5):\n        with self.lock:\n            if not self.rows:return []\n            scores=(self.w@self.word.transform([q]).T).toarray().ravel()*.55+(self.c@self.char.transform([q]).T).toarray().ravel()*.45\n            ranked=[]\n            for i in np.argsort(-scores):\n                row=dict(self.rows[i])\n                if not active(row):continue\n                if category and row['intent']!=category: continue\n                row['score']=round(float(scores[i]),4)\n                ranked.append(row)\n                if len(ranked)>=limit: break\n            return ranked\n","sha256":"a1f51311e281542faceef732c44e23aaa9fec8917c253394dd3cdbd32600bb7a"}],"qa":{"question":"Hai bộ TF-IDF có phải dùng chung một từ vựng?","answer":"Không. Pipeline phân loại fit trên Train có nhãn; chỉ mục truy hồi word/char fit trên nội dung FAQ được duyệt. Hai bước có mục đích và chuẩn hóa khác nhau."}},{"id":"evidence","title":"07 · Kiểm tra đủ bằng chứng?","group":"Luồng chat","flow":"Các hình thoi đủ khớp? xung đột? khớp năm/từ? → answered, clarify hoặc out_of_scope.","method":"Ngưỡng tương đồng và kiểm tra từ vựng/năm học bằng quy tắc kỹ thuật.","implementation":"route() kiểm tra ứng viên, ngưỡng .30/.13 và chênh lệch .025 theo điều kiện. evidence_matches() kiểm tra năm trong câu hỏi có trong FAQ, rồi kiểm tra tỷ lệ từ ngoài nhóm từ phổ biến. Nếu yếu hoặc xung đột thì return clarify.","say":"Em không coi nhãn dự đoán là bằng chứng. Em kiểm tra nội dung FAQ có đủ khớp không; nếu chưa đủ thì hỏi lại thay vì tự tạo câu trả lời.","caution":"Các ngưỡng là quy tắc khởi tạo chưa tối ưu trên tập độc lập; kiểm tra này không chứng minh FAQ luôn đúng về mặt ngữ nghĩa.","refs":[{"path":"app/engine.py","line":42,"end_line":48,"code":"def evidence_matches(question,row):\n    text=normalize(row['question']+' '+row.get('aliases','')+' '+row['answer'])\n    query=normalize(question)\n    terms=set(query.split())-EVIDENCE_STOP-EVIDENCE_TOPIC\n    years=set(re.findall(r'\\b20\\d{2}\\b',query))\n    if not years\u003c=set(re.findall(r'\\b20\\d{2}\\b',text)):return False\n    return len(terms)\u003c2 or len(terms & set(text.split()))/len(terms)>=.25","sha256":"a1f51311e281542faceef732c44e23aaa9fec8917c253394dd3cdbd32600bb7a"},{"path":"app/engine.py","line":154,"end_line":162,"code":"        if not ranked or (not topics and ranked[0]['score']\u003cRETRIEVAL_MIN_GLOBAL):\n            return {**detail,'status':'out_of_scope','fallback_reason':'insufficient_retrieval_evidence','answer':'Mình chưa có nguồn đã duyệt đủ khớp để trả lời câu hỏi này. Bạn có thể hỏi rõ hơn hoặc liên hệ đơn vị phụ trách trên website trường.','sources':[],'suggestions':['Quy định học phí','Học bổng HaUI','Đăng ký ký túc xá']}\n        top=ranked[0]\n        conflict=not topics and global_ranked and global_ranked[0]['intent']!=top['intent'] and global_ranked[0]['score']>top['score']+RETRIEVAL_MIN_MARGIN\n        close_topics=not topics and len(global_ranked)>1 and global_ranked[0]['intent']!=global_ranked[1]['intent'] and global_ranked[0]['score']-global_ranked[1]['score']\u003cRETRIEVAL_MIN_MARGIN\n        if top['score']\u003cRETRIEVAL_MIN_TOPIC or conflict or close_topics or not evidence_matches(q,top):\n            return {**detail,'status':'clarify','fallback_reason':'weak_or_conflicting_evidence','answer':'Mình chưa tìm được câu trả lời đủ khớp hoặc còn nhiều chủ đề phù hợp. Bạn mô tả rõ thủ tục, học kỳ hoặc vấn đề cần hỗ trợ nhé.','sources':[],'suggestions':[r['question'] for r in ranked[:3]]}\n        source={'id':top['id'],'title':top['source_title'],'url':top['source_url'],'reviewed_at':top['reviewed_at'],'valid_until':top.get('valid_until'),'kind':top.get('kind','guidance')}\n        return {**detail,'status':'answered','answer':top['answer'],'sources':[source],'intent':top['intent'],'intent_label':LABELS[top['intent']],'retrieval_score':top['score'],'score_note':'Điểm tương đồng truy hồi, không phải xác suất câu trả lời đúng.','suggestions':[r['question'] for r in ranked[1:4]],'evidence':top['answer']}","sha256":"a1f51311e281542faceef732c44e23aaa9fec8917c253394dd3cdbd32600bb7a"}],"qa":{"question":"Vì sao đã phân loại rồi còn hỏi lại?","answer":"Phân loại chỉ chọn nhóm. Câu có thể thiếu thông tin, sai năm, không có FAQ đủ khớp hoặc mô hình chọn nhầm nhóm nên cần một bước kiểm tra riêng."}},{"id":"generate","title":"08 · Diễn đạt bằng Qwen và fallback","group":"Luồng chat","flow":"Nhánh tùy chọn gọi AI khi đã có FAQ; lỗi hoặc không hợp lệ → giữ FAQ.","method":"Sinh văn bản có điều kiện từ nội dung truy hồi; kiểm tra JSON, số liệu và URL.","implementation":"generate() chỉ đi tiếp khi status=\"answered\", AI bật và lấy được khóa. Nó gửi câu hỏi + evidence của FAQ; chỉ thay result[\"answer\"] nếu parsed[\"supported\"] là True và các kiểm tra đạt. except hoặc kiểm tra không đạt giữ câu trả lời cũ; finally giải phóng khóa.","say":"Qwen là mô hình có sẵn dùng để diễn đạt thông tin đã tìm được. Em không huấn luyện Qwen bằng 50 câu. Khi AI lỗi, chatbot dùng lại câu trả lời đã duyệt.","caution":"Kiểm tra số, URL và supported chỉ giảm lỗi, không bảo đảm mọi diễn đạt được nguồn hỗ trợ. Lời gọi generate() được trace không đồng nghĩa provider thực sự đã được gọi.","refs":[{"path":"app/engine.py","line":165,"end_line":170,"code":"    def generate(self,question,result,settings):\n        \"\"\"Return grounded prose; citations are attached by the server, never invented by the LLM.\"\"\"\n        if result['status']!='answered' or not settings.get('enabled',True):return result\n        if not self.generator_lock.acquire(timeout=2):\n            return {**result,'generation':{'used':False,'reason':'busy','message':'AI đang bận; hiển thị câu trả lời từ kho đã duyệt.'}}\n        try:","sha256":"a1f51311e281542faceef732c44e23aaa9fec8917c253394dd3cdbd32600bb7a"},{"path":"app/engine.py","line":184,"end_line":194,"code":"            parsed=json.loads(payload)\n            answer=parsed.get('answer','')\n            # Fail closed for new numbers, URLs, missing support, or malformed output.\n            nums=lambda s:{str(float(n.replace(',','.'))) for n in re.findall(r'\\d+(?:[.,]\\d+)?',s)}\n            valid=parsed.get('supported') is True and isinstance(answer,str) and 15\u003c=len(answer)\u003c=2200 and not re.search(r'https?://|www\\.',answer) and nums(answer)\u003c=nums(result['evidence'])\n            if valid: result['answer']=answer\n            result['generation']={'used':bool(valid),'model':settings.get('model','qwen3:4b'),'provider':provider,'latency_ms':round((time.perf_counter()-t)*1000),'reason':None if valid else 'validation_fallback'}\n        except Exception:\n            result['generation']={'used':False,'reason':'provider_unavailable','message':'Tạm dùng câu trả lời từ kho đã duyệt vì dịch vụ AI chưa sẵn sàng.'}\n        finally:self.generator_lock.release()\n        return result","sha256":"a1f51311e281542faceef732c44e23aaa9fec8917c253394dd3cdbd32600bb7a"}],"qa":{"question":"MLP có sinh ra đoạn trả lời này không?","answer":"Không. MLP/LinearSVC phân loại ý định; FAQ cung cấp nội dung; Qwen có thể diễn đạt lại, còn server gắn nguồn."}},{"id":"provider","title":"Provider · Gọi mô hình có sẵn","group":"Luồng chat","flow":"Mũi tên Engine → Provider AI → Engine.","method":"HTTP client gọi Ollama hoặc API tương thích OpenAI; JSON theo schema.","implementation":"Nhánh Ollama gọi /api/chat với model qwen3:4b, stream=false và schema answer/supported. Ollama là phần mềm phục vụ mô hình, Qwen là mô hình. Trace chỉ thấy request/response ở ranh giới HTTP, không thấy từng phép tính trong Qwen.","say":"Ở đây em chỉ ra dòng c.post gửi nội dung tới Ollama. Đây là sử dụng mô hình đã huấn luyện sẵn, khác với phần em huấn luyện bộ phân loại bằng sklearn.","caution":"Không gọi Ollama là thuật toán phân loại; không diễn giải sự kiện HTTP thành trace nội bộ của mô hình ngôn ngữ.","refs":[{"path":"app/engine.py","line":176,"end_line":179,"code":"                if provider=='ollama':\n                    schema={'type':'object','properties':{'answer':{'type':'string'},'supported':{'type':'boolean'}},'required':['answer','supported'],'additionalProperties':False}\n                    r=c.post('http://127.0.0.1:11435/api/chat',json={'model':settings.get('model','qwen3:4b'),'messages':[{'role':'system','content':system},{'role':'user','content':content}],'think':False,'stream':False,'format':schema,'options':{'temperature':0,'num_predict':450,'num_ctx':4096,'seed':42}})\n                    r.raise_for_status();payload=r.json()['message']['content']","sha256":"a1f51311e281542faceef732c44e23aaa9fec8917c253394dd3cdbd32600bb7a"}],"qa":{"question":"Ollama và Qwen khác nhau thế nào?","answer":"Qwen là mô hình ngôn ngữ; Ollama chạy mô hình và cung cấp API HTTP để backend gọi."}},{"id":"persist","title":"09 · Lưu và trả kết quả","group":"Luồng chat","flow":"API → SQLite lưu hai tin nhắn → trả JSON cho trình duyệt.","method":"Lưu dữ liệu theo phiên, truy vấn có tham số và tách bằng chứng nội bộ khỏi response.","implementation":"chat() bỏ trường evidence, đo latency, tạo message ID, rồi INSERT user và assistant bằng dấu ? và tuple tham số. Nguồn được tạo ở route() từ metadata FAQ, không lấy URL do AI tự nghĩ ra.","say":"Sau khi có kết quả, em lưu câu hỏi và câu trả lời theo phiên rồi trả JSON. Phần này là quản lý dữ liệu ứng dụng, không phải huấn luyện mô hình.","caution":"Không lấy thời gian của một lượt có trace để công bố benchmark; trace và truyền dữ liệu có overhead.","refs":[{"path":"app/main.py","line":161,"end_line":168,"code":"    result.pop('evidence',None);result['latency_ms']=round((time.perf_counter()-started)*1000)\n    result['id']=secrets.token_hex(12)\n    with span('db','chat() · INSERT messages',{'question':q,'answer':result['answer']}) as save_trace, conn() as c:\n        c.execute('INSERT INTO messages VALUES(?,?,?,?,?,?)',(secrets.token_hex(12),sid,'user',q,None,now()))\n        c.execute('INSERT INTO messages VALUES(?,?,?,?,?,?)',(result['id'],sid,'assistant',result['answer'],json.dumps(result,ensure_ascii=False),now()))\n        save_trace.output={'rows_written':2,'assistant_message_id':result['id']}\n    return result\n@app.post('/api/feedback')","sha256":"15a5d2b0094977629f36847fab3c3df590b1976d57b4d4c74e45f155a5608089"},{"path":"app/engine.py","line":161,"end_line":162,"code":"        source={'id':top['id'],'title':top['source_title'],'url':top['source_url'],'reviewed_at':top['reviewed_at'],'valid_until':top.get('valid_until'),'kind':top.get('kind','guidance')}\n        return {**detail,'status':'answered','answer':top['answer'],'sources':[source],'intent':top['intent'],'intent_label':LABELS[top['intent']],'retrieval_score':top['score'],'score_note':'Điểm tương đồng truy hồi, không phải xác suất câu trả lời đúng.','suggestions':[r['question'] for r in ranked[1:4]],'evidence':top['answer']}","sha256":"a1f51311e281542faceef732c44e23aaa9fec8917c253394dd3cdbd32600bb7a"}],"qa":{"question":"Vì sao dùng dấu ? trong SQL?","answer":"Để truyền tham số tách khỏi câu lệnh SQL, tránh nối trực tiếp dữ liệu người dùng vào cấu trúc truy vấn."}},{"id":"train","title":"Huấn luyện · Học, chọn, đánh giá","group":"Nghiên cứu","flow":"Sơ đồ huấn luyện: đọc 50 câu → Train → Validation → lưu lựa chọn → Test → lưu pipeline.","method":"Học có giám sát, chia tập cố định và lựa chọn theo Macro-F1 Validation.","implementation":"30 câu Train dùng fit; 10 Validation dùng chọn 4 cấu hình MLP/2 LinearSVC. selection.json được ghi trước Test. 10 Test được measure sau lựa chọn; không refit Train+Validation. joblib.dump lưu cả vectorizer và classifier để suy luận dùng đúng pipeline.","say":"Em tách ba vai trò: Train để học trọng số, Validation để chọn cấu hình, Test để báo cáo sau lựa chọn. Mô hình được lưu cùng tiền xử lý nên khi chạy không train lại mỗi câu hỏi.","caution":"Test đã từng được xem trong lần thực nghiệm trước, không phải tập đánh giá độc lập mới. Dữ liệu tự biên soạn ít, chưa đại diện sinh viên thực tế.","refs":[{"path":"scripts/train.py","line":62,"end_line":65,"code":"    splits = {s: [r for r in rows if r['split'] == s] for s in ('Train', 'Validation', 'Test')}\n    assert len(rows) == 50 and [len(splits[s]) for s in splits] == [30, 10, 10]\n    assert set(r['intent'] for r in rows) == set(RESEARCH_LABELS)\n    assert len({r['id'] for r in rows}) == 50","sha256":"cbec61aa580d8fbf3b70723a8d51428a41ef4eac9e6cc8fa42870ec8f911e10a"},{"path":"scripts/train.py","line":118,"end_line":128,"code":"    name, selected_pipe, best = max(finalists, key=lambda c: (c[2]['validation']['macro_f1'], c[0] == 'LinearSVC'))\n    selection = dict(selected=name, selected_at=timestamp(), validation_macro_f1=best['validation']['macro_f1'],\n                     configuration=best['configuration'], dataset_sha256=sha(dataset),\n                     research_primary='MLP', test_previously_seen=True, test_evaluated_in_this_run=False,\n                     reason='Macro-F1 Validation cao nhất; hòa ưu tiên LinearSVC vì suy luận tuyến tính đơn giản. Không chọn bằng Test.',\n                     evaluation_status=report['evaluation_status'],\n                     family_selections={n: i['configuration'] for n, p, i in finalists})\n    (ROOT/'reports').mkdir(exist_ok=True)\n    write(ROOT/'reports'/'selection.json', selection)  # Persist before first Test predict.\n    report['selection'] = selection\n    report['test_evaluation_started_at'] = timestamp()","sha256":"cbec61aa580d8fbf3b70723a8d51428a41ef4eac9e6cc8fa42870ec8f911e10a"},{"path":"scripts/train.py","line":130,"end_line":132,"code":"    for name, pipe, item in finalists:\n        test = measure(pipe, splits['Test'])\n        train = measure(pipe, splits['Train'])","sha256":"cbec61aa580d8fbf3b70723a8d51428a41ef4eac9e6cc8fa42870ec8f911e10a"}],"qa":{"question":"Vì sao không chọn mô hình theo điểm Test?","answer":"Nếu dùng Test để lựa chọn hoặc chỉnh cấu hình thì Test tham gia phát triển mô hình và đánh giá sẽ lạc quan; vì thế lựa chọn dựa Validation."}},{"id":"evaluate","title":"Đánh giá · Nhãn khác câu trả lời","group":"Nghiên cứu","flow":"Khối đo kết quả và báo cáo thực nghiệm, tách khỏi đường đi chat trực tiếp.","method":"Accuracy, Macro-F1, precision/recall từng lớp và confusion matrix.","implementation":"measure() lấy nhãn thật và pipe.predict(), gọi các hàm metrics của sklearn. Accuracy đếm tỷ lệ đúng; Macro-F1 lấy trung bình F1 của 5 lớp. Đánh giá chọn FAQ được lưu riêng trong reports/faq-evaluation.json.","say":"Cả hai mô hình đạt 7/10 câu Test đúng. Em phân biệt đúng nhãn với đúng FAQ: một câu có thể nhận đúng lịch thi nhưng chọn nhầm hướng dẫn cụ thể.","caution":"Một lỗi trên 10 câu thay đổi accuracy 10 điểm phần trăm. Không suy ra chất lượng chatbot thực tế hoặc khẳng định MLP luôn thắng.","refs":[{"path":"scripts/train.py","line":48,"end_line":57,"code":"def measure(pipe, rows):\n    actual = [r['intent'] for r in rows]\n    predicted = pipe.predict([r['question'] for r in rows])\n    return dict(accuracy=accuracy_score(actual, predicted),\n                macro_f1=f1_score(actual, predicted, labels=RESEARCH_LABELS, average='macro', zero_division=0),\n                per_class=classification_report(actual, predicted, labels=RESEARCH_LABELS, output_dict=True, zero_division=0),\n                confusion_matrix=confusion_matrix(actual, predicted, labels=RESEARCH_LABELS).tolist(),\n                predictions=[dict(id=r['id'], question=r['question'], true=r['intent'], predicted=str(p))\n                             for r, p in zip(rows, predicted)])\n","sha256":"cbec61aa580d8fbf3b70723a8d51428a41ef4eac9e6cc8fa42870ec8f911e10a"}],"qa":{"question":"Vì sao dùng Macro-F1 ngoài Accuracy?","answer":"Macro-F1 cho mỗi lớp trọng số bằng nhau, giúp nhìn chất lượng giữa các chủ đề; confusion matrix cho biết các nhãn bị nhầm với nhau."}},{"id":"startup","title":"Khởi động · Nạp mô hình và chỉ mục","group":"Nghiên cứu","flow":"Khối Engine lúc startup: nạp pipeline đã lưu; xây chỉ mục từ FAQ được phép dùng.","method":"Nạp artifact joblib và xây chỉ mục TF-IDF trong bộ nhớ.","implementation":"Engine.__init__() nạp mlp.joblib và linearsvc.joblib, đọc selection.json để chọn mặc định. rebuild() lọc active(), tạo các vectorizer truy hồi và fit trên FAQ. Đây là nạp mô hình đã học, không phải huấn luyện lại bộ phân loại.","say":"Huấn luyện xảy ra ở script riêng. Khi ứng dụng khởi động, em nạp pipeline đã lưu và xây chỉ mục FAQ để phục vụ truy vấn.","caution":"Thay file mô hình không tự thay đối tượng đã nạp trong process. Trace một lượt chat không chứng minh startup vừa chạy.","refs":[{"path":"app/engine.py","line":56,"end_line":60,"code":"        for name in ('mlp','linearsvc'):\n            p=ROOT/'models'/f'{name}.joblib'\n            if p.exists(): self.models[name]=joblib.load(p)\n        p=ROOT/'reports'/'selection.json'\n        self.default_model=json.loads(p.read_text())['selected'].lower() if p.exists() else 'linearsvc'","sha256":"a1f51311e281542faceef732c44e23aaa9fec8917c253394dd3cdbd32600bb7a"},{"path":"app/engine.py","line":62,"end_line":73,"code":"    def rebuild(self,rows):\n        rows=[dict(r) for r in rows if active(dict(r))]\n        with self.lock:\n            self.rows=rows\n            if rows:\n                self.word=TfidfVectorizer(preprocessor=normalize,ngram_range=(1,2),sublinear_tf=True)\n                self.char=TfidfVectorizer(preprocessor=normalize,analyzer='char_wb',ngram_range=(3,5),sublinear_tf=True)\n                texts=[r['question']+' '+r.get('aliases','')+' '+r['answer'][:1000] for r in rows]\n                self.w=self.word.fit_transform(texts);self.c=self.char.fit_transform(texts)\n            self.version+=1\n\n    @traced('engine', ('q','category','limit'))","sha256":"a1f51311e281542faceef732c44e23aaa9fec8917c253394dd3cdbd32600bb7a"}],"qa":{"question":"intent.joblib có phải file Engine đang nạp không?","answer":"Không. Engine hiện nạp mlp.joblib và linearsvc.joblib theo tên, rồi chọn mặc định qua reports/selection.json."}},{"id":"approval","title":"Quản trị · Duyệt tri thức","group":"Nghiên cứu","flow":"Tài liệu tải lên → bản nháp → người biên tập FAQ → duyệt → cập nhật chỉ mục.","method":"Trích văn bản, kiểm tra metadata và duyệt thủ công trước khi sử dụng.","implementation":"upload_document() nhận TXT/PDF/DOCX và lưu documents ở trạng thái draft. validate_faq() kiểm tra nguồn và trạng thái; chỉ active() mới được đưa vào Engine. Việc tải tài liệu không tự huấn luyện MLP hay tự công bố câu trả lời.","say":"Em tách nhập tài liệu với duyệt tri thức. Người quản trị phải biên tập nội dung và gắn nguồn trước khi FAQ được dùng để trả lời.","caution":"PDF scan cần OCR trước; không khẳng định hệ thống hiểu hoặc kiểm chứng tự động mọi nội dung tài liệu.","refs":[{"path":"app/engine.py","line":38,"end_line":39,"code":"def active(r):\n    return r.get('status')=='approved' and (not r.get('valid_until') or r['valid_until']>=date.today().isoformat())","sha256":"a1f51311e281542faceef732c44e23aaa9fec8917c253394dd3cdbd32600bb7a"},{"path":"app/main.py","line":252,"end_line":260,"code":"def validate_faq(body):\n    if body.intent not in LABELS:raise HTTPException(422,'Nhóm câu hỏi không hợp lệ.')\n    if body.status not in ('approved','draft','archived'):raise HTTPException(422,'Trạng thái không hợp lệ.')\n    if body.kind not in ('guidance','policy','notice'):raise HTTPException(422,'Loại nguồn không hợp lệ.')\n    if not safe_url(body.source_url):raise HTTPException(422,'Nguồn phải là HTTPS trên tên miền chính thức haui.edu.vn.')\n    if body.reviewed_at>date.today():raise HTTPException(422,'Ngày rà soát không được nằm trong tương lai.')\n    if body.valid_until and body.valid_until\u003cbody.reviewed_at:raise HTTPException(422,'Ngày hết hiệu lực phải sau ngày rà soát.')\n    return body.model_dump(mode='json')\n@app.post('/api/admin/faqs',dependencies=[Depends(admin)])","sha256":"15a5d2b0094977629f36847fab3c3df590b1976d57b4d4c74e45f155a5608089"}],"qa":{"question":"Upload PDF có làm mô hình học thêm không?","answer":"Không. File được trích văn bản và lưu nháp; kho FAQ cập nhật qua biên tập/duyệt, còn huấn luyện classifier là quy trình riêng."}}]};

