/* Flowchart-to-code teaching layer. Runtime evidence remains in the trace UI. */
(() => {
  'use strict';
  const lessons = window.HauiDefenseLessons.lessons;
  const byId = new Map(lessons.map(lesson => [lesson.id, lesson]));
  const el = (tag, className, text) => {
    const node = document.createElement(tag);
    if (className) node.className = className;
    if (text !== undefined) node.textContent = text;
    return node;
  };

  function resolve(hint, context) {
    if (byId.has(context.lesson)) return context.lesson;
    const node = context.node || '';
    const diagram = context.diagram || '';
    const routing = {
      input:'normalize',rules:'rules',topics:'rules',multiple:'rules','multiple-exit':'rules',
      'rules-out-exit':'rules','rules-greeting-exit':'rules',vague:'evidence','vague-exit':'evidence',
      classify:'classify',global:'search',category:'classify',ranked:'search',enough:'evidence',
      'enough-exit':'evidence',conflict:'evidence','conflict-exit':'evidence',lexical:'evidence',
      'lexical-exit':'evidence',answer:'persist'
    };
    if (diagram === 'routing' && routing[node]) return routing[node];
    if (diagram === 'research-training' && ['train','pipe','disk'].includes(node)) return 'train';
    if (diagram === 'knowledge-admin') return 'approval';
    if (diagram === 'startup' && node !== 'web') return 'startup';
    if (diagram === 'modules' && node === 'text') return 'normalize';
    if (diagram === 'modules' && node === 'model-tools') return 'train';
    if (diagram === 'modules' && node === 'tests') return 'evaluate';
    if (hint.includes('SELECT history')) return 'history';
    if (hint.includes('INSERT messages')) return 'persist';
    if (hint.includes('evidence_matches')) return 'evidence';
    if (hint.includes('Engine.classify')) {
      const model = context.record?.output?.model;
      return model === 'MLPClassifier' ? 'mlp' : model === 'LinearSVC' ? 'svc' : 'classify';
    }
    if (hint.includes('Engine.search')) return 'search';
    if (hint.includes('Engine.generate')) return 'generate';
    if (hint.includes('httpx.Client.post')) return 'provider';
    if (hint.includes('Engine.route')) return 'routing';
    if (hint.includes('normalize')) return 'normalize';
    if (hint.includes('Engine.__init__') || hint.includes('rebuild') || hint.includes('lifespan') || hint.includes('init_db')) return 'startup';
    if (hint.includes('scripts/train') || hint.includes('Pipeline.fit') || hint.includes('joblib.dump')) return 'train';
    if (hint.includes('message()') || node === 'db') return 'persist';
    if (['provider','llm'].includes(node)) return 'provider';
    if (node === 'models') return 'startup';
    if (node === 'train') return 'train';
    if (hint.includes('chat(') || hint.includes('runLiveChat') || hint.includes('ask(') || ['browser','web','main','api'].includes(node)) return 'request';
    return null;
  }

  function runtimeNote(record) {
    if (!record) return 'Chưa chọn lời gọi. Gửi câu hỏi rồi chọn một sự kiện để đối chiếu với bước lưu đồ.';
    if (record.error) return 'Lời gọi này phát sinh lỗi. Xem lỗi thật ở Output; nội dung phương pháp bên dưới không khẳng định nhánh thành công đã chạy.';
    if (!record.finished) return 'Lời gọi đang chạy; chưa có Output cuối để kết luận nhánh thực thi.';
    const output = record.output;
    if (record.function.includes('classify') && output === null) return 'Lời gọi phân loại đã kết thúc với null: không có kết quả mô hình được dùng ở bước này (ví dụ chế độ chỉ truy hồi).';
    if (output?.routing) {
      const route = output.routing;
      return `Kết quả thật: ${output.status}. routing.reason=${route.reason}; classifier_used=${route.classifier_used}. ${route.classifier_used ? 'Nhãn mô hình đã quyết định nhóm tìm kiếm.' : 'Không kết luận nhãn mô hình đã quyết định nhóm tìm kiếm.'}`;
    }
    if (record.function.includes('evidence_matches')) return `Kết quả kiểm tra thật: ${String(output)}. Đây là kiểm tra theo quy tắc từ vựng/năm học.`;
    if (output?.generation) return `AI trong kết quả thật: used=${output.generation.used}; reason=${output.generation.reason ?? 'không có'}. Xem sự kiện HTTP riêng để biết provider có được gọi không.`;
    if (output?.model) return `Mô hình thực sự trả kết quả: ${output.model}; nhãn=${output.intent}; loại điểm=${output.score_type}. Nội bộ sklearn không được trace từng phép tính.`;
    return 'Đã quan sát lời gọi này. Input/Output ở bảng trace là dữ liệu thật; giải thích phương pháp bên dưới là chú giải code, không phải các sự kiện runtime bổ sung.';
  }

  function render(container, hint = '', context = {}) {
    if (!container) return;
    container.replaceChildren();
    const id = resolve(hint, context);
    container.dataset.lessonId = id || '';
    container.append(el('h2', 'defense-heading', 'Đối chiếu lưu đồ với code'));
    const state = context.mode === 'live' ? runtimeNote(context.record)
      : context.mode === 'offline' ? 'Đang xem kịch bản minh họa offline. Các đoạn code dưới đây chụp từ checkout hiện tại; Input/Output của kịch bản vẫn là ví dụ theo snapshot đã ghi.'
      : 'Bài hướng dẫn theo mã nguồn. Không chạy mô hình, không tạo hội thoại khi đọc hoặc đổi bài.';
    container.append(el('p', 'defense-state', state));
    if (!id) {
      container.append(el('p', '', 'Chưa có bài đối chiếu riêng cho khối này. Không gán một phương pháp hay dữ liệu giả cho khối chưa được ánh xạ.'));
      const link = el('a', '', 'Mở hướng dẫn bảo vệ đầy đủ ↗');
      link.href = '/static/huong-dan-bao-ve.html';
      link.target = '_blank';link.rel = 'noopener';container.append(link);
      return;
    }
    const lesson = byId.get(id);
    container.append(el('h3', 'defense-title', lesson.title));
    for (const [label, value] of [
      ['Lưu đồ viết gì?', lesson.flow],
      ['Phương pháp sử dụng', lesson.method],
      ['Code triển khai như thế nào?', lesson.implementation]
    ]) {
      const section = el('section', 'defense-part');
      section.append(el('h4', '', label), el('p', '', value));container.append(section);
    }
    const source = el('details', 'defense-source');
    source.open = true;
    source.append(el('summary', '', 'Chỉ vào đoạn code này khi cô hỏi'));
    for (const ref of lesson.refs) {
      const figure = el('figure', 'defense-excerpt');
      figure.append(el('figcaption', '', `${ref.path}:${ref.line}–${ref.end_line} · đoạn trích từ code hiện tại khi dựng bài`));
      const pre = el('pre', '');
      const code = el('code', '');
      code.textContent = ref.code.split('\n').map((line, index) => `${ref.line + index}  ${line}`).join('\n');
      pre.append(code);figure.append(pre);source.append(figure);
    }
    container.append(source);
    const say = el('section', 'defense-say');
    say.append(el('h4', '', 'Cách trả lời vấn đáp'), el('p', '', lesson.say));container.append(say);
    const qa = el('details', 'defense-question');
    qa.append(el('summary', '', 'Cô hỏi tiếp: ' + lesson.qa.question), el('p', '', lesson.qa.answer));container.append(qa);
    container.append(el('p', 'defense-caution', lesson.caution));
  }

  function initializeGuide() {
    const list = document.querySelector('[data-defense-list]');
    const panel = document.querySelector('[data-defense-guide]');
    if (!list || !panel) return;
    const buttons = new Map();
    const select = id => {
      if (!byId.has(id)) id = 'request';
      render(panel, '', {lesson:id,mode:'guide'});
      for (const [key, button] of buttons) button.setAttribute('aria-pressed', String(key === id));
    };
    for (const group of [...new Set(lessons.map(item => item.group))]) {
      list.append(el('h2', '', group));
      for (const lesson of lessons.filter(item => item.group === group)) {
        const button = el('button', 'defense-choice', lesson.title);
        button.type = 'button';button.dataset.lessonId = lesson.id;
        button.setAttribute('aria-pressed', 'false');
        button.addEventListener('click', () => {location.hash = lesson.id;select(lesson.id);});
        buttons.set(lesson.id, button);list.append(button);
      }
    }
    window.addEventListener('hashchange', () => select(location.hash.slice(1)));
    select(location.hash.slice(1));
    document.querySelector('[data-defense-theme]')?.addEventListener('click', () => {
      document.documentElement.dataset.theme = document.documentElement.dataset.theme === 'dark' ? 'light' : 'dark';
    });
  }

  window.DefenseGuide = {render};
  initializeGuide();
})();

;
/* Offline teaching player. Values are illustrative, never a live application trace. */
(() => {
  'use strict';
  const model = JSON.parse(document.querySelector('#presentation-data').textContent);
  const $ = selector => document.querySelector(selector);
  const diagramSelect = $('#diagram-select');
  const scenarioSelect = $('#scenario-select');
  const stage = $('#diagram-stage');
  let diagramId = 'architecture';
  let scenarioIndex = 0;
  let stepIndex = 0;
  let playing = false;
  let timer = null;
  let selectedNode = null;
  let originalViewBox = '';

  const diagram = () => model.diagrams[diagramId];
  const scenario = () => diagram().scenarios[scenarioIndex];
  const steps = () => scenario().steps;

  function stop() {
    clearTimeout(timer);
    timer = null;
    playing = false;
    $('#play').textContent = '▶ Phát';
    $('#play').setAttribute('aria-pressed', 'false');
  }

  function schedule() {
    clearTimeout(timer);
    if (!playing) return;
    timer = setTimeout(() => {
      if (stepIndex >= steps().length - 1) {
        stop();
        $('#playback-status').textContent = 'Đã hoàn tất kịch bản. Bấm Phát để chạy lại.';
        return;
      }
      showStep(stepIndex + 1);
      schedule();
    }, Number($('#speed').value) * 1000);
  }

  function valueCard(value) {
    const box = document.createElement('div');
    if (value && typeof value === 'object' && !Array.isArray(value)) {
      box.className = 'value-list';
      for (const [key, content] of Object.entries(value)) {
        const row = document.createElement('div');
        row.className = 'value-row';
        const label = document.createElement('span');
        label.className = 'value-key';
        label.textContent = key;
        const result = document.createElement('span');
        result.className = 'value-content';
        result.textContent = typeof content === 'object' ? JSON.stringify(content, null, 2) : String(content);
        row.append(label, result);
        box.append(row);
      }
    } else {
      box.className = 'value-content';
      box.textContent = typeof value === 'string' ? value : JSON.stringify(value, null, 2);
    }
    return box;
  }

  function updateIO(step, inspecting = false) {
    $('#step-title').textContent = step.title;
    $('#step-explanation').textContent = step.explain;
    $('#function-name').textContent = step.fn || diagram().nodeLabels[step.node];
    $('#input-value').replaceChildren(valueCard(step.input));
    $('#output-value').replaceChildren(valueCard(step.output));
    $('#input-json').textContent = JSON.stringify(step.input, null, 2);
    $('#output-json').textContent = JSON.stringify(step.output, null, 2);
    $('#speaker-note').textContent = step.say || step.explain;
    window.DefenseGuide.render($('#defense-step'), step.fn || '', {mode:'offline',node:step.node,diagram:diagramId});
    $('#branch-status').textContent = inspecting ? 'Khám phá khối · ngoài bước đang phát' : (step.condition || 'Bước trong kịch bản minh họa');
    $('#branch-status').classList.toggle('is-inferred', Boolean(step.inferred));
    const refs = step.sources || diagram().sources[step.node] || [];
    $('#source-links').replaceChildren();
    for (const ref of refs) {
      const link = document.createElement('a');
      link.href = `huong-dan-source.html#path=${encodeURIComponent(ref.path)}&line=${ref.line}`;
      link.target = '_blank';
      link.rel = 'noopener';
      link.textContent = `${ref.path}:${ref.line}${ref.end_line !== ref.line ? '–' + ref.end_line : ''}`;
      $('#source-links').append(link);
    }
  }

  function focusGraph(step) {
    const svg = stage.querySelector('svg');
    const ids = step.nodes || [step.node];
    const edgeIds = step.edges || [];
    const completed = new Set(steps().slice(0, stepIndex).map(s => s.node));
    let active = null;
    for (const node of svg.querySelectorAll('[data-node-id]')) {
      const id = node.getAttribute('data-node-id');
      const current = ids.includes(id);
      node.classList.toggle('demo-active', current);
      node.classList.toggle('demo-done', !current && completed.has(id));
      node.setAttribute('aria-pressed', String(current));
      if (id === step.node) active = node;
    }
    for (const edge of svg.querySelectorAll('[data-edge-id]')) {
      edge.classList.toggle('demo-edge', edgeIds.includes(edge.getAttribute('data-edge-id')));
    }
    if ($('#follow-node').checked && active) {
      const bounds = active.getBBox();
      const [, , width, height] = originalViewBox.split(/\s+/).map(Number);
      const focusWidth = Math.min(width, Math.max(520, bounds.width + 240));
      const focusHeight = Math.min(height, Math.max(310, bounds.height + 160));
      const x = Math.max(0, Math.min(width - focusWidth, bounds.x + bounds.width / 2 - focusWidth / 2));
      const y = Math.max(0, Math.min(height - focusHeight, bounds.y + bounds.height / 2 - focusHeight / 2));
      svg.setAttribute('viewBox', `${x} ${y} ${focusWidth} ${focusHeight}`);
    } else {
      svg.setAttribute('viewBox', originalViewBox);
    }
  }

  function showStep(index) {
    stepIndex = Math.max(0, Math.min(index, steps().length - 1));
    const step = steps()[stepIndex];
    selectedNode = step;
    updateIO(step);
    focusGraph(step);
    $('#step-number').textContent = `${stepIndex + 1} / ${steps().length}`;
    $('#playback-status').textContent = playing ? 'Đang phát kịch bản minh họa' : 'Đang dừng · có thể giải thích từng bước';
    $('#previous').disabled = stepIndex === 0;
    $('#next').disabled = stepIndex === steps().length - 1;
    $('#progress').value = stepIndex;
    for (const [index, button] of [...$('#step-list').children].entries()) {
      button.classList.toggle('current', index === stepIndex);
      button.classList.toggle('completed', index < stepIndex);
      if (index === stepIndex) button.setAttribute('aria-current', 'step');
      else button.removeAttribute('aria-current');
    }
  }

  function selectNode(id) {
    stop();
    const found = steps().findIndex((step, index) => index >= stepIndex && step.node === id);
    const fallback = steps().findIndex(step => step.node === id);
    if (found >= 0 || fallback >= 0) {
      showStep(found >= 0 ? found : fallback);
      return;
    }
    const step = diagram().inspector[id];
    if (!step) return;
    selectedNode = step;
    updateIO(step, true);
    focusGraph(step);
    $('#playback-status').textContent = 'Đang xem riêng một khối. Bấm Tiếp để trở lại kịch bản.';
  }

  function loadScenario() {
    stop();
    $('#scenario-description').textContent = scenario().description;
    $('#progress').max = steps().length - 1;
    $('#step-list').replaceChildren();
    steps().forEach((step, index) => {
      const button = document.createElement('button');
      button.type = 'button';
      button.className = 'step-item';
      button.textContent = `${String(index + 1).padStart(2, '0')}  ${step.title}`;
      button.addEventListener('click', () => { stop(); showStep(index); });
      $('#step-list').append(button);
    });
    showStep(0);
  }

  function loadDiagram() {
    stop();
    const current = diagram();
    $('#diagram-title').textContent = current.label;
    $('#original-link').href = `${diagramId}.html`;
    stage.innerHTML = current.svg;
    const svg = stage.querySelector('svg');
    originalViewBox = svg.getAttribute('viewBox');
    for (const node of svg.querySelectorAll('[data-node-id]')) {
      const id = node.getAttribute('data-node-id');
      node.setAttribute('aria-label', `Xem đầu vào và đầu ra: ${current.nodeLabels[id]}`);
      node.addEventListener('click', () => selectNode(id));
      node.addEventListener('keydown', event => {
        if (event.key === 'Enter' || event.key === ' ') { event.preventDefault(); selectNode(id); }
      });
    }
    scenarioSelect.replaceChildren();
    current.scenarios.forEach((item, index) => scenarioSelect.add(new Option(item.label, index)));
    scenarioIndex = 0;
    loadScenario();
  }

  function togglePlayback() {
    if (playing) { stop(); $('#playback-status').textContent = 'Đã tạm dừng để thuyết trình'; return; }
    if (stepIndex === steps().length - 1) showStep(0);
    playing = true;
    $('#play').textContent = 'Ⅱ Tạm dừng';
    $('#play').setAttribute('aria-pressed', 'true');
    showStep(stepIndex);
    schedule();
  }

  for (const [id, item] of Object.entries(model.diagrams)) diagramSelect.add(new Option(item.label, id));
  diagramSelect.value = diagramId;
  diagramSelect.addEventListener('change', () => { diagramId = diagramSelect.value; loadDiagram(); });
  scenarioSelect.addEventListener('change', () => { scenarioIndex = Number(scenarioSelect.value); loadScenario(); });
  $('#play').addEventListener('click', togglePlayback);
  $('#next').addEventListener('click', () => { stop(); showStep(stepIndex + 1); });
  $('#previous').addEventListener('click', () => { stop(); showStep(stepIndex - 1); });
  $('#restart').addEventListener('click', () => { stop(); showStep(0); });
  $('#progress').addEventListener('input', () => { stop(); showStep(Number($('#progress').value)); });
  $('#speed').addEventListener('change', schedule);
  $('#follow-node').addEventListener('change', () => focusGraph(selectedNode));
  $('#theme').addEventListener('click', () => {
    document.documentElement.dataset.theme = document.documentElement.dataset.theme === 'dark' ? 'light' : 'dark';
  });
  $('#fullscreen').addEventListener('click', async () => {
    try {
      if (document.fullscreenElement) await document.exitFullscreen();
      else await document.documentElement.requestFullscreen();
    } catch { $('#playback-status').textContent = 'Có thể dùng F11 để mở toàn màn hình trong trình duyệt.'; }
  });
  document.addEventListener('keydown', event => {
    if (event.target.closest('input,select,textarea,button,[data-node-id],a,summary') || event.altKey || event.ctrlKey || event.metaKey) return;
    if (event.key === ' ') { event.preventDefault(); togglePlayback(); }
    if (event.key === 'ArrowRight') { event.preventDefault(); stop(); showStep(stepIndex + 1); }
    if (event.key === 'ArrowLeft') { event.preventDefault(); stop(); showStep(stepIndex - 1); }
  });
  document.addEventListener('visibilitychange', () => {
    if (document.hidden && playing) { stop(); $('#playback-status').textContent = 'Đã tạm dừng khi chuyển sang cửa sổ khác.'; }
  });
  loadDiagram();
})();

